    "impossible_must_have", "two_messages", "one_message",
)


def load_buyer(name, path):
    spec = importlib.util.spec_from_file_location(name, path / "buyer/__init__.py", submodule_search_locations=[str(path / "buyer")])
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return importlib.import_module(f"{name}.runner"), importlib.import_module(f"{name}.policy")


class LocalClient:
    """Transport adapter only: all negotiation and scoring behavior stays in official Sim."""

    def __init__(self, case, facts):
        self.sim = Sim({case["case_id"]: copy.deepcopy(case)}, facts=facts, clock=lambda: 1_000_000.0)
        self.sent = []
        self.case = case
        self.proposal_violations = []

    def call(self, method, *args):
        try:
            return copy.deepcopy(method("local", *args))
        except Fail as exc:
            raise ArenaError(exc.status, exc.detail) from None

    def open_session(self, case_id):
        return self.call(self.sim.open, case_id)

    def send_message(self, session_id, supplier_id, message):
        self.sent.append(copy.deepcopy({"supplier": supplier_id, "message": message}))
        for sheet in message.get("term_sheets") or []:
            terms = sheet["terms"]
            std = self.sim.sessions[session_id]["threads"][supplier_id]["standard"]
            if not must_haves_ok(self.case, terms, std):
                self.proposal_violations.append({"supplier": supplier_id, "terms": terms, "reason": "must_haves"})
        return self.call(self.sim.message, session_id, supplier_id, message)

    def attachment(self, session_id, attachment_id):
        return self.call(self.sim.attachment, session_id, attachment_id)[0]

    def session(self, session_id):
        return self.call(self.sim.state, session_id)

    def thread(self, session_id, supplier_id):
        return self.call(self.sim.thread, session_id, supplier_id)


def change(case, scenario):
    case = copy.deepcopy(case)
    b = case["buyer"]
    if scenario == "interest_20pct":
        b["interest_rate"] = 0.20
    elif scenario == "freight_x3":
        b["freight_eur_per_unit"] = {k: 3 * v for k, v in b["freight_eur_per_unit"].items()}
    elif scenario == "delivery_penalty_x3":
        b["late_cost_per_day"] = 3 * b.get("late_cost_per_day", 0)
    elif scenario == "quality_cost_x3":
        b["cost_per_defect"] = 3 * b.get("cost_per_defect", 0)
    elif scenario == "relationship_charge_x3":
        b["relationship_eur_per_point"] = 3 * b.get("relationship_eur_per_point", 0)
    elif scenario == "longer_horizon":
        b["horizon_years"] += 1
    elif scenario == "payment_floor_60":
        b["must_haves"] = [*b.get("must_haves", []), {"field": "payment_days", "op": ">=", "value": 60}]
    elif scenario == "impossible_must_have":
        b["must_haves"] = [*b.get("must_haves", []), {"field": "payment_days", "op": ">=", "value": 1000}]
    elif scenario == "strong_alternative":
        terms = {**case.get("fixed_terms", {}), "unit_price": round(0.85 * (b.get("current_unit_price") or b["fallback_unit_price"]), 2),
                 "payment_days": b["reference_payment_days"], "contract_months": int(b["horizon_years"] * 12),
                 "volume_per_year": b["need_per_year"], "lead_time_days": b["need_lead_time_days"],
                 "incoterm": min(b["freight_eur_per_unit"], key=b["freight_eur_per_unit"].get)}
        b["alternative"] = {"kind": "rfq", "terms": terms}
    elif scenario in ("two_messages", "one_message"):
        case["round_limit"] = 2 if scenario == "two_messages" else 1
    return case


def run(case, runner, policy, pkg, label, scenario, mode, out):
    client = LocalClient(case, pkg.facts if pkg else {})
    table = runner.RemoteTable(client)
    started = time.perf_counter()
    row = {"case": case["case_id"], "variant": label, "scenario": scenario, "data_mode": mode}
    try:
        result = runner.play_case(table, case["case_id"], pkg, complete=None)
        state = client.session(table.session_id)
        row.update({k: result.get(k) for k in ("deal", "score", "c_deal", "c_alt", "end_reason", "terms", "supplier_id")})
        row["must_haves_ok"] = result.get("must_haves_ok")
        row["accepted_worse_than_alternative"] = bool(result.get("deal") and result.get("c_alt") is not None and result["c_deal"] > result["c_alt"] + 0.01)
        row["trace"] = state["result"].get("trace", [])
        row["error"] = None
    except Exception as exc:
        row["error"] = f"{type(exc).__name__}: {exc}"
    row["runtime_s"] = round(time.perf_counter() - started, 4)
    row["proposal_violations"] = client.proposal_violations
    row["messages"] = len(client.sent)
    row["accepted_invalid"] = bool(row.get("deal") and row.get("terms") and not must_haves_ok(case, row["terms"]))
    (out / f"{label}_{mode}_{scenario}_{case['case_id'].split(':')[-1]}.json").write_text(json.dumps(row, indent=2, default=str))
    return {k: v for k, v in row.items() if k != "trace"}


def fingerprints(path):
    return {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((path / "buyer").glob("*.py"))}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--baseline", type=Path, required=True)
    ap.add_argument("--candidate", type=Path, required=True)
    ap.add_argument("--cases", type=Path, required=True)
    ap.add_argument("--data", type=Path, required=True)
    ap.add_argument("--out", type=Path, required=True)
    args = ap.parse_args()
    logging.basicConfig(level=logging.ERROR)
    cases = load_cases()
    sources = {k: "official-simulator" for k in cases}
    for path in sorted(args.cases.glob("*.json")):
        for case in json.loads(path.read_text()):
            case = {k: v for k, v in case.items() if k != "hosted"}
            cases[case["case_id"]] = case
            sources[case["case_id"]] = path.name
    args.out.mkdir(parents=True, exist_ok=True)
    details = args.out / "runs"
    details.mkdir(exist_ok=True)
    pkg = DataPackage(args.data)
    pkg.lookup("")
    modules = {label: load_buyer(f"local_{label}", path) for label, path in (("baseline", args.baseline), ("candidate", args.candidate))}
    for label, (runner, _) in modules.items():
        runner.RUNS = args.out / "decisions" / label
    metadata = {"cases": sources, "scenarios": SCENARIOS, "data_modes": ["package", "case_only"], "baseline": fingerprints(args.baseline),
                "candidate": fingerprints(args.candidate), "data_facts_sha256": hashlib.sha256(json.dumps(pkg.facts, sort_keys=True).encode()).hexdigest(),
                "hosted_sessions": 0, "model_calls": 0, "simulator": "unmodified official fixed supplier; virtual frozen clock",
                "limitations": ["Simulator scores do not predict hosted performance.", "Synthetic cases are variations, not additional released cases.", "No LLM wording effects are measured."]}
    (args.out / "metadata.json").write_text(json.dumps(metadata, indent=2))
    rows = []
    for mode in ("package", "case_only"):
        for scenario in SCENARIOS:
            for case_id, original in sorted(cases.items()):
                case = change(original, scenario)
                for label, (runner, policy) in modules.items():
                    rows.append(run(case, runner, policy, pkg if mode == "package" else None, label, scenario, mode, details))
            print(json.dumps({"completed": len(rows), "data_mode": mode, "scenario": scenario, "errors": sum(bool(r["error"]) for r in rows)}), flush=True)
            (args.out / "results.json").write_text(json.dumps(rows, indent=2, default=str))
    groups = {}
    for label in modules:
        for mode in metadata["data_modes"]:
            for scenario in SCENARIOS:
                selected = [r for r in rows if (r["variant"], r["data_mode"], r["scenario"]) == (label, mode, scenario)]
                scores = [r["score"] for r in selected if isinstance(r.get("score"), (int, float)) and math.isfinite(r["score"])]
                groups[f"{label}/{mode}/{scenario}"] = {"runs": len(selected), "errors": sum(bool(r["error"]) for r in selected),
                    "deals": sum(bool(r.get("deal")) for r in selected), "invalid_deals": sum(r["accepted_invalid"] for r in selected),
                    "worse_than_alternative": sum(bool(r.get("accepted_worse_than_alternative")) for r in selected),
                    "runs_with_invalid_proposals": sum(bool(r["proposal_violations"]) for r in selected),
                    "simulator_mean_score": statistics.mean(scores) if scores else None}
    (args.out / "summary.json").write_text(json.dumps(groups, indent=2))
    print(json.dumps({"runs": len(rows), "unique_cases": len(cases), "errors": sum(bool(r["error"]) for r in rows)}))


if __name__ == "__main__":
    main()
